type PushResult = 'ok' | 'full';

class Ring {
  private readonly buf: Float32Array;   // fixed, typed memory - no GC churn
  private readonly mask: number;
  private head = 0; private tail = 0;    // one slot wasted to disambiguate full/empty

  constructor(sizePow2: number) {
    this.buf = new Float32Array(sizePow2);
    this.mask = sizePow2 - 1;
  }
  push(v: number): PushResult {         // typed result, not a magic sentinel
    const next = (this.head + 1) & this.mask;
    if (next === this.tail) return 'full';
    this.buf[this.head] = v;
    this.head = next;
    return 'ok';
  }
  pop(): number | undefined {
    if (this.tail === this.head) return undefined;
    const v = this.buf[this.tail];
    this.tail = (this.tail + 1) & this.mask;
    return v;
  }
}
// across workers: SharedArrayBuffer + Atomics for the indices (Atomics.wait is
// worker-only; the main thread polls). For MPMC/blocking, use a bounded library queue.
